// The whole document, as canvas.toObject(['egId','egLabel','egSource','egRole']).
export const fabricDocument = (imageUrl: string, opts: { objects?: unknown[]; rsvp?: boolean } = {}) => ({
  version: '7.4.0',
  objects: opts.objects ?? [
    fabricImage(imageUrl),
    fabricRect(),
    fabricCircle(),
    fabricLine(),
    fabricText(),
    ...(opts.rsvp === false ? [] : [fabricRsvpButton()]),
  ],
  background: '#FAF7F2',
});

// Fabric 7.4.0's canvas.toSVG() for that document, verbatim (the 4:5 card;
// `format` swaps the size for the 9:16 one). `body` replaces the drawing.
export const fabricSvg = (imageUrl: string, opts: { format?: CanvasFormat; rsvp?: boolean; body?: string; viewBox?: string } = {}) => {
  const height = CANVAS_FORMATS[opts.format ?? '4:5'];
  const viewBox = opts.viewBox ?? `0 0 1080 ${height}`;
  const rsvpMarker = opts.rsvp === false ? '' : ' data-evelope-action="rsvp"';
  const body = opts.body ?? `<rect x="0" y="0" width="100%" height="100%" fill="#FAF7F2"></rect>
<g transform="matrix(3 0 0 3 166.5 1.5)"  >
\t<image style="stroke: none; stroke-width: 0; stroke-dasharray: none; stroke-linecap: butt; stroke-dashoffset: 0; stroke-linejoin: miter; stroke-miterlimit: 4; fill: rgb(0,0,0); fill-rule: nonzero; opacity: 1;"  xlink:href="${imageUrl}" x="-0.5" y="-0.5" width="1" height="1"></image>
</g>
<g transform="matrix(1 0 0 1 541 634)"  >
<rect style="stroke: rgb(244,185,66); stroke-width: 3; stroke-dasharray: none; stroke-linecap: butt; stroke-dashoffset: 0; stroke-linejoin: miter; stroke-miterlimit: 4; fill: none; fill-rule: nonzero; opacity: 1;"  x="-459.5" y="-594.5" rx="23" ry="23" width="919" height="1189" />
</g>
<g transform="matrix(1 0 0 1 540.5 600.5)"  >
<circle style="stroke: none; stroke-width: 1; stroke-dasharray: none; stroke-linecap: butt; stroke-dashoffset: 0; stroke-linejoin: miter; stroke-miterlimit: 4; fill: rgb(108,76,241); fill-rule: nonzero; opacity: 0.5;"  cx="0" cy="0" r="100" />
</g>
<g transform="matrix(1 0 0 1 292.5 600)"  >
<line style="stroke: rgb(31,41,55); stroke-width: 2; stroke-dasharray: none; stroke-linecap: butt; stroke-dashoffset: 0; stroke-linejoin: miter; stroke-miterlimit: 4; fill: rgb(0,0,0); fill-rule: nonzero; opacity: 1;"  x1="-165.5" y1="0" x2="165.5" y2="0" />
</g>
<g transform="matrix(1 0 0 1 540.5 292.88)" style=""  >
\t\t<text xml:space="preserve" font-family="Great Vibes" font-size="120" font-style="italic" font-weight="bold" style="stroke: none; stroke-width: 1; stroke-dasharray: none; stroke-linecap: butt; stroke-dashoffset: 0; stroke-linejoin: miter; stroke-miterlimit: 4; fill: rgb(31,41,55); fill-rule: nonzero; opacity: 1; text-decoration-thickness: 6.6667%; white-space: pre;" ><tspan x="-269.7949" y="-36.8832" >Thandi &amp;</tspan><tspan x="-169.3066" y="112.2768" >Sipho</tspan></text>
</g>
${opts.rsvp === false ? '' : `<g transform="matrix(1 0 0 1 540.5 1096.5)"${rsvpMarker}  >
<g style=""   >
\t\t<g transform="matrix(1 0 0 1 0 0)"  >
<rect style="stroke: none; stroke-width: 1; stroke-dasharray: none; stroke-linecap: butt; stroke-dashoffset: 0; stroke-linejoin: miter; stroke-miterlimit: 4; fill: rgb(108,76,241); fill-rule: nonzero; opacity: 1;"  x="-170" y="-48" rx="18" ry="18" width="340" height="96" />
</g>
\t\t<g transform="matrix(1 0 0 1 0 -3.4)" style=""  >
\t\t<text xml:space="preserve" font-family="Poppins" font-size="40" font-style="normal" font-weight="bold" style="stroke: none; stroke-width: 1; stroke-dasharray: none; stroke-linecap: butt; stroke-dashoffset: 0; stroke-linejoin: miter; stroke-miterlimit: 4; fill: rgb(255,255,255); fill-rule: nonzero; opacity: 1; text-decoration-thickness: 6.6667%; white-space: pre;" ><tspan x="-111.0547" y="12.5656" >RSVP NOW</tspan></text>
</g>
</g>
</g>`}`;
  return `<?xml version="1.0" encoding="UTF-8" standalone="no" ?>
<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">
<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" version="1.1" width="1080" height="${height}" viewBox="${viewBox}" xml:space="preserve">
<desc>Created with Fabric.js 7.4.0</desc>
<defs>
</defs>
${body}
</svg>`;
};

// A minimal SVG around `inner`, for attack payloads: the right size, no RSVP.
export const svgAround = (inner: string, format: CanvasFormat = '4:5') =>
  `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 1080 ${CANVAS_FORMATS[format]}">${inner}</svg>`;
